from typing import Dict, List, Any
import json

class Renderer:
    @staticmethod
    def from_format(format):
        FORMAT_REGISTRY = {
            'csv': CsvRenderer,
            'json': JsonRenderer,
            'html': HtmlRenderer,
        }
        return FORMAT_REGISTRY[format]()

class CsvRenderer:
    def render(self, data: List[Dict[str, Any]]):
        lines = []
        header = ', '.join(data[0].keys())
        lines.append(header)
        for row in data:
            lines.append(','.join(str(v) for v in row.values()))
        return '\n'.join(lines)

class JsonRenderer:
    def render(self, data: List[Dict[str, Any]]):
        import json
        return json.dumps(data, indent=2)

class HtmlRenderer:
    def render(self, data: List[Dict[str, Any]]):
        rows_html = ''
        for row in data:
            cells = ''.join(f'<td>{v}</td>' for v in row.values())
            rows_html += f'<tr>{cells}</tr>'
        headers = ''.join(f'<th>{k}</th>' for k in data[0].keys())
        return f'<table><thead><tr>{headers}</tr></thead><tbody>{rows_html}</tbody></table>'

class ReportGenerator:
    def generate(self, data: List[Dict[str, Any]], format: str):
        renderer = Renderer.from_format(format)
        return renderer.render(data)
